solution.solution.cpp:
#include <cstdint>
#include <map>
#include <optional>

constexpr std::uint64_t PAGE{ 4096 };
struct Entry { std::uint64_t frame; bool writable; };
enum class Access { Ok, NotMapped, ReadOnly };

std::uint64_t pageOf(std::uint64_t address) { return address / PAGE; }
std::uint64_t offsetIn(std::uint64_t address) { return address % PAGE; }

std::uint64_t pagesSpanned(std::uint64_t address, std::uint64_t size)
{
    if (size == 0) return 0;
    return pageOf(address + size - 1) - pageOf(address) + 1;
}

Access check(const std::map<std::uint64_t, Entry>& table, std::uint64_t address, std::uint64_t size, bool write)
{
    if (size == 0) return Access::Ok;
    bool readOnly{ false };
    for (std::uint64_t page{ pageOf(address) }; page <= pageOf(address + size - 1); ++page)
    {
        const auto it{ table.find(page) };
        if (it == table.end()) return Access::NotMapped;
        if (write && !it->second.writable) readOnly = true;
    }
    return readOnly ? Access::ReadOnly : Access::Ok;
}

std::optional<std::uint64_t> translate(const std::map<std::uint64_t, Entry>& table, std::uint64_t address)
{
    const auto it{ table.find(pageOf(address)) };
    if (it == table.end()) return std::nullopt;
    return it->second.frame * PAGE + offsetIn(address);
}

unitTests:
using Table = std::map<std::uint64_t, Entry>;
static const Table table{ { 0x140, { 0x9A, false } }, { 0x141, { 0x03, true } }, { 0x142, { 0x7F, true } }, { 0x200, { 0x10, true } } };

TEST("pages and offsets") {
    CHECK_EQ(pageOf(0x12345), 0x12ull);
    CHECK_EQ(offsetIn(0x12345), 0x345ull);
    CHECK_EQ(pageOf(4095), 0ull);
    CHECK_EQ(pageOf(4096), 1ull);
    CHECK_EQ(offsetIn(0x140FFF), 0xFFFull);
}
TEST("pages spanned") {
    CHECK_EQ(pagesSpanned(0x1000, 4096), 1ull);
    CHECK_EQ(pagesSpanned(0x1FFC, 8), 2ull);
    CHECK_EQ(pagesSpanned(0x1000, 1), 1ull);
    CHECK_EQ(pagesSpanned(0x1800, 8192), 3ull);
    CHECK_EQ(pagesSpanned(0x5000, 0), 0ull);
}
TEST("access checks") {
    CHECK(check(table, 0x141010, 8, true) == Access::Ok);
    CHECK(check(table, 0x140010, 8, false) == Access::Ok);
    CHECK(check(table, 0x140010, 8, true) == Access::ReadOnly);
    CHECK(check(table, 0x141FFC, 8, true) == Access::Ok);
    CHECK(check(table, 0x142FFC, 8, false) == Access::NotMapped);
    CHECK(check(table, 0x18, 4, false) == Access::NotMapped);
    CHECK(check(table, 0x140FFC, 8, true) == Access::ReadOnly);
    CHECK(check(table, 0x1F0000, 0, true) == Access::Ok);
}
TEST("translation") {
    CHECK_EQ(translate(table, 0x141234).value_or(0), 0x3234ull);
    CHECK_EQ(translate(table, 0x140000).value_or(0), 0x9A000ull);
    CHECK_EQ(translate(table, 0x200FFF).value_or(0), 0x10FFFull);
    CHECK(!translate(table, 0x143000).has_value());
    CHECK(!translate(table, 0).has_value());
}

